import base64
import os

# Full Base64 string from browser subagent
b64_data = """"""

pdf_data = base64.b64decode(b64_data)
output_path = 'raw_pdfs/sac_judge_176_2548.pdf'
os.makedirs(os.path.dirname(output_path), exist_ok=True)
with open(output_path, 'wb') as f:
    f.write(pdf_data)
print(f"Saved {len(pdf_data)} bytes to {output_path}")
